<?php require __DIR__.'/bootstrap.php';admin();$statuses=['pending_payment','paid','processing','shipped','delivered','cancelled','refunded'];if(requestPost())failSafe(function()use($statuses){$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'');if(!in_array($status,$statuses,true))throw new RuntimeException('Invalid status.');$s=db()->prepare('SELECT status FROM orders WHERE id=?');$s->execute([$id]);$old=$s->fetchColumn();if($old===false)throw new RuntimeException('Order not found.');if($status==='paid'||$status==='refunded')throw new RuntimeException('Payment/refund status must be verified through the payment provider, not manually set.');if($old==='pending_payment'&&$status!=='cancelled')throw new RuntimeException('Unpaid orders cannot be fulfilled.');if(in_array($old,['cancelled','refunded'],true))throw new RuntimeException('Cannot change a cancelled or refunded order.');if($status==='pending_payment')throw new RuntimeException('Cannot reset an order to pending payment.');$s=db()->prepare('UPDATE orders SET status=? WHERE id=?');$s->execute([$status,$id]);flash('Order status updated.');go('orders.php?view='.$id);});$selected=(int)($_GET['view']??0);$order=null;$items=[];if($selected){$s=db()->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$selected]);$order=$s->fetch();if($order){$s=db()->prepare('SELECT * FROM order_items WHERE order_id=?');$s->execute([$selected]);$items=$s->fetchAll();}}$orders=db()->query('SELECT id,public_id,customer_name,email,total_paise,status,created_at FROM orders ORDER BY created_at DESC LIMIT 300')->fetchAll();layout('Orders','orders.php');?><section class="panel"><div class="panelhead"><h2>Recent orders</h2><span class="muted">Latest 300</span></div><div class="tablewrap"><table><thead><tr><th>Reference</th><th>Customer</th><th>Total</th><th>Status</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($orders as $o):?><tr><td><?=e(substr($o['public_id'],0,12))?></td><td><?=e($o['customer_name'])?><small><?=e($o['email'])?></small></td><td><?=price($o['total_paise'])?></td><td><span class="status"><?=e($o['status'])?></span></td><td><?=e($o['created_at'])?></td><td><a href="?view=<?=e($o['id'])?>">Details</a></td></tr><?php endforeach;?></tbody></table></div></section><?php if($order):$address=json_decode($order['shipping_address'],true)??[];?><section class="panel"><h2>Order <?=e($order['public_id'])?></h2><div class="detailgrid"><div><h3>Customer</h3><p><?=e($order['customer_name'])?></p><p><?=e($order['email'])?> · <?=e($order['phone'])?></p><h3>Shipping</h3><p><?=e(implode(', ',array_filter(array_map('strval',$address))))?></p></div><div><h3>Payment and fulfillment</h3><p>Status: <strong><?=e($order['status'])?></strong></p><p>Razorpay order: <?=e($order['razorpay_order_id']??'Not created')?></p><p>Payment ID: <?=e($order['razorpay_payment_id']??'Not captured')?></p><form method="post" class="form"><input type="hidden" name="csrf" value="<?=e(token())?>"><input type="hidden" name="id" value="<?=e($order['id'])?>"><label>Update fulfillment<select name="status"><?php foreach(['processing','shipped','delivered','cancelled'] as $status):?><option value="<?=e($status)?>" <?= $order['status']===$status?'selected':'' ?>><?=e(ucwords(str_replace('_',' ',$status)))?></option><?php endforeach;?></select></label><button class="btn">Update order</button></form><p class="muted">Paid and refunded states can only be changed through verified payment processing.</p></div></div><h3>Items</h3><div class="tablewrap"><table><thead><tr><th>Item</th><th>Size / color / GSM</th><th>Qty</th><th>Unit price</th></tr></thead><tbody><?php foreach($items as $i):?><tr><td><?=e($i['title'])?><?= $i['custom_design']?'<small>Custom design metadata present</small>':'' ?></td><td><?=e($i['size'])?> / <?=e($i['color'])?> / <?=e($i['gsm'])?></td><td><?=e($i['quantity'])?></td><td><?=price($i['unit_price_paise'])?></td></tr><?php endforeach;?></tbody></table></div><p class="total">Total <?=price($order['total_paise'])?></p></section><?php endif;endLayout();
